sys_ui_context_menu.action_script:
//var nsProTaskMain;

//nsProTaskMain = parent.top.window.gsft_main;

assignHostPortsToLocalCircuit();

function assignHostPortsToLocalCircuit() {
    var selectedLocalCircuit = g_sysId;

    //alert(g_sysId);
    var circuit = new GlideAjax('x_g_sonc_ns_pro.circuit_ajax');
    circuit.addParam('sysparm_name', 'getPendingLocalCircuitInformation');
    circuit.addParam('sysparm_selectedLocalCircuit', selectedLocalCircuit);
    circuit.getXMLAnswer(getResponse);

    function getResponse(response) {
        alert(response);
        response = JSON.parse(response);
        //alert(response.resultCode);
        if (response.resultCode == "success") {
            var localCircuit = response.localCircuit;
            var proposedHostCircuitId = response.proposedHostCircuitId;
            var priSecCircuit = response.priSecCircuit;
			var proposedCircuitID = response.proposedCircuitID;
            var proposedTelco = response.proposedTelcoProvider;
            if (!proposedHostCircuitId) {
                alert('Pending PE Host Circuit ID must be populated on the circuit prior to assigning host ports');
                return;
            } else {
                openPortsList(localCircuit,proposedHostCircuitId,priSecCircuit,proposedCircuitID,proposedTelco);

            }
            location.reload();
        } else {
            return false;
        }

    }
                function openPortsList(localCircuit,proposedHostCircuitId,priSecCircuit,proposedCircuitID,proposedTelco) {

                    var selectedHostCircuit = proposedHostCircuitId;
                    var selectedTelcoProvider = proposedTelco;
                    var selectedLocalCircuitName = proposedCircuitID
                    var selectedLocalCircuitSysID = localCircuit;
                    var localCircuitInfo = {};
                    localCircuitInfo.selectedLocalCircuitName = selectedLocalCircuitName;
                    localCircuitInfo.selectedTelcoProvider = selectedTelcoProvider;
                    localCircuitInfo.selectedHostCircuitSysId = selectedHostCircuit;
					localCircuitInfo.selectedLocalCircuitSysID = selectedLocalCircuitSysID;
                    g_scratchpad.localCircuitInfo = localCircuitInfo;
                    var parmFixedQuery = "siteISEMPTY^install_statusIN1,4^ip_addressSTARTSWITH172.^pe_host_circuit_id=" + selectedHostCircuit;

                    var url;
                    url = new GlideURL("x_g_sonc_ns_pro_port_list.do");
                    url.addParam("sysparm_fixed_query", parmFixedQuery);
                    url.addParam("sysparm_view", "availproposedportcircuit");
                    url.addParam("sysparm_view_forced", true);


                    var portListW = new GlideOverlay({
                        title: getMessage('Select Ports to Assign to Local Circuit ' + selectedLocalCircuitName),
                        iframe: url.getURL(),
                        draggable: true,
                        allowOverflowX: true,
                        scroll: true,
                        height: "100%",
                        width: "100%",
                        closeOnEscape: true,
                        //onAfterLoad: resizeIframe,
                        onAfterClose: function() {
                            location.reload();

                        }
                    });


                    portListW.setPreference('sysparm_sys_id', selectedHostCircuit);
                    portListW.render();
                    g_list.refresh(1);
                    //w.destroy();



                }


}

sys_ui_context_menu.on_show_script:
canBeConfigured();

function canBeConfigured() {

    var proposed = false;
	related = g_list.getRelated();

    if (related == "REL:5ea9196387a95a10f9f20f280cbb358c") {
        proposed = true;
    }
    if (proposed) {
        g_menu.setEnabled(g_item);
        g_menu.setLabel(g_item, "<b style='color:DodgerBlue;'>• Assign Host Ports to Local Circuit •</b>");

    } else {
        g_menu.setDisabled(g_item);
    }

}
